function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2);
  ctx.lineTo(W/2 - 50, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2);
  ctx.lineTo(W/2 + 50, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('empty', W/2, H/2 + 80);
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 120, 10 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('nothing left', W/2, H/2 + 150 + 10 * Math.sin(t));
  ctx.restore();
}
